UPDATE `#__jem_venue_capacity_profiles` AS `p` INNER JOIN `#__jem_venues` AS `v` ON `v`.`id` = `p`.`venue_id` SET `p`.`capacity` = `v`.`capacity` WHERE `p`.`capacity` = 0;
INSERT INTO `#__jem_config` (`keyname`,`value`) VALUES ('venue_profile_capacity_migrated','1') ON DUPLICATE KEY UPDATE `value` = '1';
UPDATE `#__jem_venue_capacity_profiles` SET `name` = 'Main' WHERE `code` = 'default' AND `name` = 'Default configuration';
