DELETE FROM `#__jem_venue_capacity_profiles` WHERE `code` = 'default' AND NOT EXISTS (SELECT 1 FROM `#__jem_venue_profile_spaces` WHERE `venue_profile_id` = `#__jem_venue_capacity_profiles`.`id`) AND NOT EXISTS (SELECT 1 FROM `#__jem_events` WHERE `venue_profile_id` = `#__jem_venue_capacity_profiles`.`id`) AND NOT EXISTS (SELECT 1 FROM `#__jem_event_space_layouts` WHERE `venue_profile_id` = `#__jem_venue_capacity_profiles`.`id`);

